To illustrate my concern, here's my current code:

```cpp
Des d1;
char* plaintext = new char[64];
char* ciphertext = new char[64];
ifstream h("requisiti.txt", ios::in | ios::binary);
ofstream k("requisiti2.txt", ios::out | ios::binary);

while (!h.eof()) {
    h.read(plaintext, 64);
    ciphertext = d1.Encrypt(plaintext); // decryption is similar, just swap Encrypt for Decrypt
    k.write(ciphertext, 64);
}

h.close();
k.close();
remove("requisiti.txt");
rename("requisiti2.txt", "requisiti.txt");
```

