 @GetMapping("/doLogin")
 public String login(
 @SessionAttribute("SPRING_SECURITY_SAVED_REQUEST") SavedRequest originalRequest,
 HttpServletResponse response) throws IOException {
 String originalUrl = originalRequest.getRedirectUrl();
