 while (!p.gcd(q).equals(BigInteger.valueOf(1)));

 n = p.multiply(q);
 BigInteger phiN = p.subtract(BigInteger.valueOf(1)).
 multiply(q.subtract(BigInteger.valueOf(1)));

 do
 e = new BigInteger(bits, new Random());
